{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-UYqApX/src/line-parser.js","content":"/**
 * A cursor over a single source line. Every directive fits on one line,
 * so a `LineParser` never crosses a newline: reaching the end of its
 * text, or an unquoted `#`/`;`, both mean "nothing meaningful is left
 * on this line".
 */
import { fail } from './errors.js'
import { makeTable } from './nodes.js'

const BARE_NAME_CHAR = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT_DIGITS = '[0-9]+(?:_[0-9]+)*'
const FLOAT_INT = `[+-]?${FLOAT_DIGITS}`
const FLOAT_FRAC = `\\.${FLOAT_DIGITS}`
const FLOAT_EXP = `[eE][+-]?${FLOAT_DIGITS}`
const FLOAT_RE = new RegExp(`^${FLOAT_INT}(?:${FLOAT_FRAC}${FLOAT_EXP}?|${FLOAT_EXP})$`)
const BARE_STOP_CHARS = new Set([' ', '\t', ',', ']', '}'])

function normalizeIntToBigInt(token) {
  const cleaned = token.replace(/_/g, '')
  const withoutPlus = cleaned.startsWith('+') ? cleaned.slice(1) : cleaned
  return BigInt(withoutPlus)
}

export class LineParser {
  constructor(text, lineNo) {
    this.text = text
    this.lineNo = lineNo
    this.pos = 0
  }

  atEnd() {
    return this.pos >= this.text.length
  }

  peek() {
    return this.text[this.pos]
  }

  // True once nothing meaningful remains on the line: the text ran out,
  // or an unquoted comment marker starts here.
  atLineEnd() {
    if (this.atEnd()) return true
    const c = this.peek()
    return c === '#' || c === ';'
  }

  skipWS() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  fail(reason) {
    fail(this.lineNo, reason)
  }

  parseName() {
    this.skipWS()
    if (this.atLineEnd()) this.fail('expected a name')
    const c = this.peek()
    if (c === '"') return this.parseBasicStringRaw()
    if (c === "'") return this.parseLiteralStringRaw()
    const start = this.pos
    while (!this.atEnd() && BARE_NAME_CHAR.test(this.peek())) this.pos++
    if (this.pos === start) this.fail('expected a name')
    return this.text.slice(start, this.pos)
  }

  parseDottedName() {
    const parts = [this.parseName()]
    for (;;) {
      this.skipWS()
      if (this.atEnd() || this.peek() !== '.') break
      this.pos++
      this.skipWS()
      parts.push(this.parseName())
    }
    return parts
  }

  parseBasicStringRaw() {
    this.pos++ // opening quote
    let out = ''
    for (;;) {
      if (this.atEnd()) this.fail('unterminated string')
      const c = this.peek()
      if (c === '"') {
        this.pos++
        return out
      }
      if (c === '\\') {
        this.pos++
        if (this.atEnd()) this.fail('unterminated string')
        const e = this.peek()
        if (e === '"') {
          out += '"'
          this.pos++
        } else if (e === '\\') {
          out += '\\'
          this.pos++
        } else if (e === 'n') {
          out += '\n'
          this.pos++
        } else if (e === 't') {
          out += '\t'
          this.pos++
        } else if (e === 'r') {
          out += '\r'
          this.pos++
        } else if (e === '0') {
          out += '\0'
          this.pos++
        } else if (e === 'u') {
          const hex = this.text.slice(this.pos + 1, this.pos + 5)
          if (hex.length === 4 && /^[0-9A-Fa-f]{4}$/.test(hex)) {
            out += String.fromCharCode(parseInt(hex, 16))
            this.pos += 5
          } else {
            this.fail('invalid escape \\u')
          }
        } else {
          this.fail(`invalid escape \\${e}`)
        }
      } else {
        out += c
        this.pos++
      }
    }
  }

  parseLiteralStringRaw() {
    this.pos++ // opening quote
    const start = this.pos
    for (;;) {
      if (this.atEnd()) this.fail('unterminated string')
      if (this.peek() === "'") {
        const s = this.text.slice(start, this.pos)
        this.pos++
        return s
      }
      this.pos++
    }
  }

  parseBareValue() {
    const start = this.pos
    while (!this.atEnd() && !BARE_STOP_CHARS.has(this.peek())) this.pos++
    const token = this.text.slice(start, this.pos)
    if (token === 'true') return { type: 'boolean', value: true }
    if (token === 'false') return { type: 'boolean', value: false }
    if (INT_RE.test(token)) return { type: 'integer', big: normalizeIntToBigInt(token) }
    if (FLOAT_RE.test(token)) return { type: 'float', value: Number(token.replace(/_/g, '')) }
    this.fail(`invalid value ${token}`)
  }

  // `path` is the dotted-name path (from the document root) that this
  // value is being assigned to; it seeds an inline table's own key
  // paths so duplicate-key errors inside it can be reported from the
  // root, per the spec.
  parseValue(path) {
    this.skipWS()
    if (this.atLineEnd() || (!this.atEnd() && ',]}'.includes(this.peek()))) this.fail('expected a value')
    const c = this.peek()
    if (c === '"') return { type: 'string', value: this.parseBasicStringRaw() }
    if (c === "'") return { type: 'string', value: this.parseLiteralStringRaw() }
    if (c === '[') return this.parseArrayValue(path)
    if (c === '{') return this.parseInlineTableValue(path)
    return this.parseBareValue()
  }

  parseArrayValue(path) {
    this.pos++ // '['
    const items = []
    this.skipWS()
    if (this.atLineEnd()) this.fail('unterminated array')
    if (this.peek() === ']') {
      this.pos++
      return { type: 'array', items }
    }
    for (;;) {
      items.push(this.parseValue(path))
      this.skipWS()
      if (this.atLineEnd()) this.fail('unterminated array')
      const c = this.peek()
      if (c === ',') {
        this.pos++
        this.skipWS()
        if (this.atLineEnd()) this.fail('unterminated array')
        if (this.peek() === ']') {
          this.pos++
          return { type: 'array', items }
        }
        continue
      }
      if (c === ']') {
        this.pos++
        return { type: 'array', items }
      }
      this.fail('unterminated array')
    }
  }

  parseInlineTableValue(path) {
    this.pos++ // '{'
    const table = makeTable()
    this.skipWS()
    if (this.atLineEnd()) this.fail('unterminated inline table')
    if (this.peek() === '}') {
      this.pos++
      return table
    }
    for (;;) {
      const relParts = this.parseDottedName()
      this.skipWS()
      if (this.atLineEnd() || this.peek() !== '=') this.fail('expected = in an inline table')
      this.pos++
      this.skipWS()
      const fullPath = path.concat(relParts)
      const value = this.parseValue(fullPath)
      assignInto(table, relParts, fullPath, value, this.lineNo)
      this.skipWS()
      if (this.atLineEnd()) this.fail('unterminated inline table')
      const c = this.peek()
      if (c === ',') {
        this.pos++
        this.skipWS()
        if (this.atLineEnd()) this.fail('unterminated inline table')
        continue // a trailing comma surfaces as "expected a name" via parseDottedName
      }
      if (c === '}') {
        this.pos++
        return table
      }
      this.fail('unterminated inline table')
    }
  }
}

// Walks `relativeParts` inside `container`, creating intermediate
// tables as it goes, and sets the final key to `value`. `fullPath` is
// the same path counted from the document root, used only to word
// errors; it is longer than `relativeParts` when `container` itself
// sits at a non-root path (an inline table's own keys).
export function assignInto(container, relativeParts, fullPath, value, lineNo) {
  const offset = fullPath.length - relativeParts.length
  let cur = container
  for (let i = 0; i < relativeParts.length - 1; i++) {
    cur = stepIntoTable(cur, relativeParts[i], fullPath, offset + i, lineNo)
  }
  const last = relativeParts[relativeParts.length - 1]
  if (cur.map.has(last)) fail(lineNo, `key ${fullPath.join('.')} is defined twice`)
  cur.map.set(last, value)
}

// Resolves one dotted-name segment while walking towards a table: an
// existing table is used as-is, an array of tables contributes its
// last element, an absent name creates a fresh table, and anything
// else is `<path> is not a table`.
export function stepIntoTable(container, name, fullPath, idx, lineNo) {
  if (container.map.has(name)) {
    const node = container.map.get(name)
    if (node.type === 'table') return node
    if (node.type === 'array-of-tables') return node.items[node.items.length - 1]
    fail(lineNo, `${fullPath.slice(0, idx + 1).join('.')} is not a table`)
  }
  const t = makeTable()
  container.map.set(name, t)
  return t
}
"}

