import { fail } from './errors.js'
import { makeTable } from './nodes.js'

const BARE_NAME_CHAR = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT_DIGITS = '[0-9]+(?:_[0-9]+)*'
const FLOAT_INT = `[+-]?${FLOAT_DIGITS}`
const FLOAT_FRAC = `\\.${FLOAT_DIGITS}`
const FLOAT_EXP = `[eE][+-]?${FLOAT_DIGITS}`
const FLOAT_RE = new RegExp(`^${FLOAT_INT}(?:${FLOAT_FRAC}${FLOAT_EXP}?|${FLOAT_EXP})$`)
const BARE_STOP_CHARS = new Set([' ', '\t', ',', ']', '}'])

function normalizeIntToBigInt(token) {
  const cleaned = token.replace(/_/g, '')
  const withoutPlus = cleaned.startsWith('+') ? cleaned.slice(1) : cleaned
  return BigInt(withoutPlus)
}

export class LineParser {
  constructor(text, lineNo) {
    this.text = text
    this.lineNo = lineNo
    this.pos = 0
  }

  atEnd() {
    return this.pos >= this.text.length
  }

  peek() {
    return this.text[this.pos]
  }

  // True once nothing meaningful remains on the line: the text ran out,
  // or an unquoted comment marker starts here.
  atLineEnd() {
    if (this.atEnd()) return true
    const c = this.peek()
    return c === '#' || c === ';'
  }

  skipWS() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  fail(reason) {
    fail(this.lineNo, reason)
  }

  parseName() {
    this.skipWS()
    if (this.atLineEnd()) this.fail('expected a name')
    const c = this.peek()
    if (c === '"') return this.parseBasicStringRaw()
    if (c === "'") return this.parseLiteralStringRaw()
    const start = this.pos
    while (!this.atEnd() && BARE_NAME_CHAR.test(this.peek())) this.pos++
    if (this.pos === start) this.fail('expected a name')
    return this.text.slice(start, this.pos)
  }

