    const parts = [this.parseName()]
    for (;;) {
      this.skipWS()
      if (this.atEnd() || this.peek() !== '.') break
      this.pos++
      this.skipWS()
      parts.push(this.parseName())
    }
    return parts
  }

  parseBasicStringRaw() {
    this.pos++ // opening quote
    let out = ''
    for (;;) {
      if (this.atEnd()) this.fail('unterminated string')
      const c = this.peek()
      if (c === '"') {
        this.pos++
        return out
      }
      if (c === '\\') {
        this.pos++
        if (this.atEnd()) this.fail('unterminated string')
