// tables as it goes, and sets the final key to `value`. `fullPath` is
// the same path counted from the document root, used only to word
// errors; it is longer than `relativeParts` when `container` itself
// sits at a non-root path (an inline table's own keys).
export function assignInto(container, relativeParts, fullPath, value, lineNo) {
