 * Parses a whole configuration document: one directive per line,
 * dispatching blank/comment lines, `[name]`/`[[name]]` headers and
 * `key = value` assignments to build the root table.
 */
import { fail } from './errors.js'
import { makeArrayOfTables, makeTable } from './nodes.js'
import { LineParser, assignInto, stepIntoTable } from './line-parser.js'

function processHeaderSingle(root, parts, lineNo) {
  let cur = root
  for (let i = 0; i < parts.length - 1; i++) cur = stepIntoTable(cur, parts[i], parts, i, lineNo)
  const last = parts[parts.length - 1]
  const path = parts.join('.')
  if (cur.map.has(last)) {
    const node = cur.map.get(last)
    if (node.type !== 'table') fail(lineNo, `${path} is not a table`)
    if (node.headerDefined) fail(lineNo, `table ${path} is defined twice`)
    node.headerDefined = true
    return node
  }
  const t = makeTable()
  t.headerDefined = true
  cur.map.set(last, t)
  return t
}

function processHeaderArray(root, parts, lineNo) {
  let cur = root
  for (let i = 0; i < parts.length - 1; i++) cur = stepIntoTable(cur, parts[i], parts, i, lineNo)
  const last = parts[parts.length - 1]
  const path = parts.join('.')
  if (cur.map.has(last)) {
    const node = cur.map.get(last)
    if (node.type !== 'array-of-tables') fail(lineNo, `${path} is not an array of tables`)
    const t = makeTable()
    node.items.push(t)
    return t
  }
  const t = makeTable()
  cur.map.set(last, makeArrayOfTables(t))
  return t
}

function parseHeaderLine(parser) {
  parser.pos++ // first '['
  let isArray = false
  if (!parser.atEnd() && parser.peek() === '[') {
    isArray = true
    parser.pos++
  }
  parser.skipWS()
  const parts = parser.parseDottedName()
  parser.skipWS()
  if (parser.atLineEnd() || parser.peek() !== ']') parser.fail('unterminated table header')
  parser.pos++
  if (isArray) {
    if (parser.atLineEnd() || parser.peek() !== ']') parser.fail('unterminated table header')
    parser.pos++
  }
  parser.skipWS()
  if (!parser.atLineEnd()) parser.fail('trailing text after a table header')
  return { isArray, parts }
}

export function parseDocument(lines) {
  const root = makeTable()
  let current = root
  let currentPath = []
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const parser = new LineParser(lines[i], lineNo)
    parser.skipWS()
    if (parser.atEnd()) continue
    const c = parser.peek()
    if (c === '#' || c === ';') continue
    if (c === '[') {
      const { isArray, parts } = parseHeaderLine(parser)
      current = isArray ? processHeaderArray(root, parts, lineNo) : processHeaderSingle(root, parts, lineNo)
      currentPath = parts
      continue
    }
    const parts = parser.parseDottedName()
    parser.skipWS()
    if (parser.atLineEnd() || parser.peek() !== '=') parser.fail('expected key = value')
    parser.pos++
    parser.skipWS()
    const fullPath = currentPath.concat(parts)
    const value = parser.parseValue(fullPath)
    parser.skipWS()
    if (!parser.atLineEnd()) parser.fail('trailing text after a value')
    assignInto(current, parts, fullPath, value, lineNo)
  }
  return root
}
