{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-UYqApX/src/format.js","content":"/**
 * Renders a parsed document as canonical JSON, or as the `keys`
 * listing, both walking every table's members in ascending key order
 * by code point.
 */

function byCodePoint(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

function sortedKeys(table) {
  return [...table.map.keys()].sort(byCodePoint)
}

export function toJSON(node, depth = 0) {
  const pad = '  '.repeat(depth)
  const padIn = '  '.repeat(depth + 1)
  switch (node.type) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const parts = keys.map((k) => `${padIn}${JSON.stringify(k)}: ${toJSON(node.map.get(k), depth + 1)}`)
      return `{\n${parts.join(',\n')}\n${pad}}`
    }
    case 'array':
    case 'array-of-tables': {
      if (node.items.length === 0) return '[]'
      const parts = node.items.map((it) => `${padIn}${toJSON(it, depth + 1)}`)
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.big.toString()
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unreachable node type ${node.type}`)
  }
}

function externalType(node) {
  return node.type === 'array-of-tables' ? 'array' : node.type
}

function collectKeyLines(node, path, out) {
  out.push(`${path} ${externalType(node)}`)
  if (node.type === 'table') {
    for (const k of sortedKeys(node)) collectKeyLines(node.map.get(k), `${path}.${k}`, out)
  } else if (node.type === 'array' || node.type === 'array-of-tables') {
    node.items.forEach((it, idx) => collectKeyLines(it, `${path}[${idx}]`, out))
  }
}

export function toKeyLines(root) {
  const out = []
  for (const k of sortedKeys(root)) collectKeyLines(root.map.get(k), k, out)
  return out
}
"}

