/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { ConfigError } from './errors.js'
import { parseDocument } from './document.js'
import { toJSON, toKeyLines } from './format.js'

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'json' && argv[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }
  const mode = argv[0]
  const input = readFileSync(0, 'utf8')
  const lines = splitLines(input)

  let root
  try {
    root = parseDocument(lines)
  } catch (e) {
    if (e instanceof ConfigError) {
      process.stderr.write(`error: line ${e.line}: ${e.reason}\n`)
      process.exit(2)
    }
    throw e
  }

  if (mode === 'json') {
    process.stdout.write(`${toJSON(root)}\n`)
  } else {
    const out = toKeyLines(root)
    process.stdout.write(out.map((l) => `${l}\n`).join(''))
  }
}

main()
"}

